import {indiaPath} from './mumbai-data.js?v=20261024-cities04';
export const mumbaiViews={
 'city-mumbai-context':[['locator','Locate Mumbai'],['site','Harbour and coast'],['connections','Connections'],['boundaries','Choose the boundary']],
 'city-mumbai-structure':[['satellite','Satellite evidence'],['centres','Several centres'],['ages','Building-age anchors'],['zones','Compare the zones']],
 'city-mumbai-growth':[['counts','Census counts'],['rates','Two decadal changes'],['balance','Population components'],['investment','Investment and location']],
 'city-mumbai-migration':[['routes','Routes and motives'],['communities','Community networks'],['services','People and services'],['composition','Age and needs']],
 'city-mumbai-inequality':[['opportunity','Unequal rewards'],['housing','Housing classification'],['livelihoods','Work and enterprise'],['access','Quality of life']]
};
export const mumbaiRequirements=Object.fromEntries(Object.entries(mumbaiViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const mumbaiAnimated=(k,v)=>k==='city-mumbai-context'?v==='connections':k==='city-mumbai-growth'?['balance','investment'].includes(v):k==='city-mumbai-migration'?['routes','services'].includes(v):k==='city-mumbai-inequality'?['opportunity','access'].includes(v):false;
export const mumbaiCensus={geography:'Greater Mumbai (Municipal Corporation)',population:[{year:1991,value:9925891},{year:2001,value:11978450},{year:2011,value:12442373}],housing:{year:2011,total:12442373,classified:5206473,reportedPercent:41.8},suburban2011:9356962};
export const mumbaiGrowth=(old,current)=>(current-old)/old*100;
export const mumbaiBalance=(start,natural,national,international)=>start+natural+national+international;
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#b9cdd3',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=6,c='#efb59e')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#e7ece8" stroke-width="1"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?70:45}" rx="12" fill="#35576a" stroke="#abc4ce"/>`+tx(x+12,y+27,a,12)+(b?tx(x+12,y+52,b,11):'');
const title=s=>tx(20,28,s,14);
const fig=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#edf2f0" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,l)=>`<a href="${u}" target="_blank" rel="noopener">${l}</a>`;
const censusURL='https://sansad.in/getFile/loksabhaquestions/annex/6/AU4082.pdf?source=pqals';
const regionalURL='https://www.mmrda.maharashtra.gov.in/sites/default/files/2021-09/Environmental%20Status%20Report_0.pdf';
const bkcURL='https://mmrda.maharashtra.gov.in/en/planning/badra-kurla-complex/overview?page=2';
const dharaviURL='https://drpmumbai.maharashtra.gov.in/en/About-Us/Dharavi-an-Overview';
const source=k=>`<p class="geo-caption">${{
 census:link(censusURL,'Government of India: Census figures, 23 December 2015')+' · '+link(regionalURL,'MMRDA: earlier census series, table 1-6')+'. Final municipal 2001/2011 counts; earlier 1991 count. Provisional 2011 values excluded. Historical observations, not current MMR population.',
 housing:link(censusURL,'Government of India, Census 2011 municipal table')+'. Official housing category, not an income-poverty or employment measure. Reported percentage rounded to one decimal; not current conditions.',
 context:link('https://mumbaicity.gov.in/en/history/','Mumbai City: historical context')+' · '+link('https://www.mmrda.maharashtra.gov.in/en/planning/regional-plan/final-rp-for-mmr','MMRDA regional planning'),
 structure:link(bkcURL,'MMRDA: BKC planning history')+' · '+link('https://whc.unesco.org/en/list/945/','UNESCO: historic railway terminus'),
 migration:link(dharaviURL,'Dharavi project authority: community and enterprise history')+' · '+link('https://www.gazetteers.maharashtra.gov.in/cultural.maharashtra.gov.in/english/gazetteer/greater_bombay/economic.html','Maharashtra Gazetteer: historical migration context')+'. Local histories are not a census of every resident or independent evaluation of redevelopment.',
 inequality:link(dharaviURL,'Dharavi project authority: livelihoods and historic services')+' · '+link(bkcURL,'MMRDA: commercial development')+'. Compare several measures and resident experiences; nearby functions do not establish every household’s circumstances.'
 }[k]}</p>`;
export function mumbaiSatellite(neutral=false){return `<figure style="margin:0"><img src="./geography/images/mumbai-landsat7-usgs.jpg" width="1000" height="1000" style="display:block;width:100%;height:auto;max-height:340px;object-fit:contain;border-radius:10px" alt="Landsat image of Mumbai’s coastal peninsula and harbour: blue-grey built-up surfaces surround dark green vegetated areas, with open sea to the left and creeks extending inland."><figcaption class="geo-caption">${link('https://science.nasa.gov/earth/earth-observatory/bombay-india-2638/','Ron Beck / USGS EROS, via NASA Earth Observatory')} · published 23 July 2002 · unchanged. False colour: blue-grey urban; dark green vegetation; light brown sparse vegetation. Acquisition date not stated on source page. ${neutral?'A single historical cover image.':'Regional cover evidence; not precise CBD boundaries, household income or present-day land use.'}</figcaption></figure>`;}
export function mumbaiEvidence(kind='counts'){
 if(kind==='satellite')return mumbaiSatellite(true);
 let b='',c='',rows=[],src='census';
 if(kind==='housing'){src='housing';const d=mumbaiCensus.housing,other=d.total-d.classified;b=title('GREATER MUMBAI · CENSUS 2011')+tx(20,58,'Residents by official housing category',12)+box(20,95,400,'Total municipal population','12,442,373 people')+box(20,195,190,'Slum category','5,206,473 people')+box(230,195,190,'Other residents',other.toLocaleString('en-GB')+' people')+tx(20,320,'Category share uses the same total and date',12);c='Read the official population category and municipal denominator. The table is about people, not land area or a direct income-poverty threshold.';rows=[['Municipal total','12,442,373'],['Slum category','5,206,473'],['Other residents',other.toLocaleString('en-GB')]];}
 else{b=title('GREATER MUMBAI · CENSUS OBSERVATIONS')+tx(20,52,'Municipal population (millions) · zero-based axis',12);const x=y=>70+(y-1991)*15,y=n=>285-n/1e6*14;for(let n=0;n<=15;n+=5)b+=path(`M60 ${y(n*1e6)}H405`,'#8ca7b655',1)+tx(24,y(n*1e6)+4,String(n),11);b+=`<polyline points="${mumbaiCensus.population.map(p=>`${x(p.year)},${y(p.value)}`).join(' ')}" fill="none" stroke="#b7d3c4" stroke-width="3"/>`;for(const p of mumbaiCensus.population)b+=dot(x(p.year),y(p.value),5)+tx(x(p.year)-20,y(p.value)-13,(p.value/1e6).toFixed(2),12)+tx(x(p.year)-17,310,String(p.year),11);b+=tx(20,339,'Joined observations; no intervening annual values',11);c='Final municipal census counts at three dates. Connecting segments help compare observations but are not annual measurements, migration components or the wider metropolitan region.';rows=mumbaiCensus.population.map(p=>[String(p.year),p.value.toLocaleString('en-GB')+' people']);}
 return fig(b,c)+source(src)+`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${kind==='housing'?'Census 2011 housing-category counts':'Greater Mumbai municipal census counts'}</caption><thead><tr><th scope="col">${kind==='housing'?'Category':'Year'}</th><th scope="col">Residents</th></tr></thead><tbody>${rows.map(([a,v])=>`<tr><th scope="row">${a}</th><td>${v}</td></tr>`).join('')}</tbody></table></details>`;
}
const towers=(x,y)=>Array.from({length:3},(_,i)=>`<rect x="${x+i*24}" y="${y-i%2*22}" width="20" height="${65+i%2*22}" fill="#a2bfc9" stroke="#d1e0df"/>`+Array.from({length:6},(_,j)=>`<rect x="${x+4+i*24+j%2*9}" y="${y+9+Math.floor(j/2)*15-i%2*22}" width="4" height="6" fill="#294a60"/>`).join('')).join('');
const homes=(x,y,n=4)=>Array.from({length:n},(_,i)=>`<path d="M${x+i*24} ${y}l10-9 10 9v24h-20Z" fill="${i%2?'#d7b79f':'#a9c3af'}" stroke="#dbe3d9"/>`).join('');
export function mumbaiScene(k,v,t=0){if(!mumbaiViews[k])return '';if(!mumbaiRequirements[k].includes(v))v=mumbaiRequirements[k][0];t=mumbaiAnimated(k,v)?Math.min(1,Math.max(0,Number(t)||0)):0;let b='',c='',src='';
 if(k==='city-mumbai-context'){
 src='context';
 if(v==='locator'){b=title('MUMBAI · INDIA’S WEST COAST')+`<path d="${indiaPath}" fill="#8ca89a" stroke="#d0ded6" stroke-width="1.4"/>`+dot(119,215.2,6)+path('M126 215H255','#efc3aa',2)+tx(260,220,'Mumbai',15)+tx(265,245,'~19.1°N, 72.9°E',12)+tx(30,275,'Arabian Sea',13)+tx(350,75,'N ↑',13)+tx(20,339,'Generalised country geometry; approximate city point',11);c='Natural Earth 110m India outline, public domain; approximate Mumbai marker for orientation. This is a national locator, not a map of municipal boundaries or detailed urban land uses.';return fig(b,c)+`<p class="geo-caption">${link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth, public domain')}</p>`;}
 if(v==='site'){b=title('HARBOUR SITE: OPPORTUNITIES AND CONSTRAINTS')+`<path d="M20 70H170L200 140 180 235 110 290H20Z" fill="#5e8d9f"/><path d="M180 70H280L300 200 255 265 190 245 215 145Z" fill="#9db59c"/><path d="M285 65Q345 125 300 215L350 295H420V65Z" fill="#7d9b8a"/>`+towers(202,125)+tx(30,130,'Arabian',12)+tx(30,150,'Sea',12)+tx(290,100,'Creeks',12)+tx(282,265,'Harbour',12)+tx(20,325,'Conceptual coast and harbour; monsoon context',12);c='A schematic isolates peninsula, harbour and creek relationships. Sea access supported trade, while low-lying coastal land and heavy monsoon rainfall create constraints. Shapes and heights are not surveyed or a flood-risk map.';}
 else if(v==='connections'){b=title('CONNECTING GOODS, PEOPLE AND INFORMATION')+box(20,65,180,'Indian hinterland','Rail / roads / suppliers')+box(240,65,180,'Global partners','Sea / air / digital links')+box(120,235,200,'Mumbai functions','Finance / trade / culture')+path('M110 145L185 225M330 145L255 225')+dot(110+75*t,145+80*t)+dot(330-75*t,145+80*t)+tx(20,332,'Symbolic links, not measured flows or travel times',11);c='Connections support regional, national and global functions, including work, trade and cultural activity. Moving tokens illustrate links, not volumes or equal access for all residents.';}
 else{b=title('MATCH THE STATISTIC TO ITS BOUNDARY')+`<ellipse cx="220" cy="180" rx="190" ry="115" fill="#426e8050" stroke="#bdd3da" stroke-dasharray="6 4"/><ellipse cx="200" cy="180" rx="110" ry="75" fill="#789b8a99" stroke="#c4d9ca"/>`+tx(118,160,'Greater Mumbai',15)+tx(119,184,'City + Suburban districts',11)+tx(75,320,'Wider metropolitan region includes other municipalities',11)+dot(340,190,7)+tx(315,226,'Navi Mumbai',11);c='Conceptual relationships, not actual boundary shapes or areas. Greater Mumbai differs from the urban agglomeration and wider MMR; Navi Mumbai is a separate urban area in the region.';}
 }
 if(k==='city-mumbai-structure'){
 if(v==='satellite')return mumbaiSatellite();src='structure';
 if(v==='centres'){b=title('NOT ONE UNIFORM BUSINESS CORE')+`<path d="M125 60Q250 40 270 140L220 290 140 270Z" fill="#7b9e8c" stroke="#c8dbcf"/>`+dot(180,250,10)+tx(240,258,'South Mumbai',13)+path('M192 250H232','#cbdcd8',1)+dot(230,135,10)+tx(280,135,'BKC',14)+path('M242 135H270','#cbdcd8',1)+dot(195,84,5)+tx(25,65,'Northern',12)+tx(25,82,'suburbs',12)+path('M100 80L185 84','#cbdcd8',1)+tx(20,330,'Approximate relative locations · not a boundary map · N ↑',11);c='South Mumbai’s historic core and BKC illustrate multiple commercial nodes. Transport corridors and mixed housing/work uses make a simple ring model insufficient. Positions and outline are schematic.';}
 else if(v==='ages'){b=title('HISTORICAL ANCHORS, MIXED BUILDING AGES')+`<path d="M40 215V130h30v-20h20v-25h20v25h20v20h30v85Z" fill="#d6b89e" stroke="#e5dfd2"/>`+towers(265,140)+tx(20,255,'Historic terminus',13)+tx(20,277,'Built 1878–1888',12)+tx(255,255,'BKC development',13)+tx(255,277,'Planning authority: 1977',11)+tx(20,330,'Icons, not building photographs; planning ≠ every build date',11);c='The historic station and later planned commercial district are dated examples. They do not date every building; redevelopment, reuse and surviving older fabric create mixed ages.';}
 else{b=title('COMPARE FUNCTIONS ACROSS THE URBAN AREA')+towers(30,100)+homes(135,170,4)+homes(270,150,3)+`<path d="M360 200l18-45 18 45Z" fill="#adc8a3"/>`+path('M20 235H420','#c1d5d5',2)+tx(30,264,'CBD',12)+tx(130,264,'Inner city',12)+tx(250,264,'Suburbs',12)+tx(350,264,'Fringe',12)+tx(20,300,'Offices / mixed industry and homes / housing / mixed edge',11)+tx(20,331,'Functional framework, not a measured cross-section',11);c='A conceptual profile compares typical functions. Actual Mumbai uses overlap, informal settlements occur in several locations and the metropolitan fringe lies beyond the core municipality.';}
 }
 if(k==='city-mumbai-growth'){
 if(v==='counts')return mumbaiEvidence();src='census';
 if(v==='rates'){b=title('TWO DECADES, SAME MUNICIPAL DEFINITION')+box(20,85,190,'1991 → 2001','Approx. +20.7%')+box(230,85,190,'2001 → 2011','Approx. +3.9%')+tx(20,235,'A smaller percentage rise is still growth',16)+tx(20,280,'(New − old) ÷ old × 100',15)+tx(20,330,'Historical municipal trend, not all MMR or today',11);c='Rates use the three displayed census counts and the starting count of each decade as denominator. They are decadal percentage changes, not annual growth rates or changes in percentage points.';}
 else if(v==='balance'){b=title('COMPONENTS OF GROWTH · INVENTED CASE')+box(20,65,185,'Natural increase','Births − deaths: +30')+box(235,65,185,'National net migration','Arrivals − departures: +15')+box(20,175,185,'International net','Arrivals − departures: −5')+tx(225,205,'Total: '+Math.round(1000+40*t),22)+tx(225,233,'Start 1,000',12)+tx(20,292,'End: 1,000 +30 +15 −5 = 1,040',14)+tx(20,330,'Not observed Mumbai component estimates',11);c='Invented balance: natural increase and both signed migration components produce total change +40. The smooth accumulation is symbolic, not measured Mumbai demography or a claim about actual component shares.';}
 else{b=title('INVESTMENT CHANGES OPPORTUNITY AND LOCATION')+box(20,70,180,'Jobs / infrastructure','Changing connections')+box(240,70,180,'Households / firms','Varied costs and choices')+path('M100 180H340M340 240H100')+dot(100+240*t,180)+dot(340-240*t,240)+tx(20,305,'Central constraints and peripheral opportunities differ',11)+tx(20,330,'Investment is not itself a measured population count',11);c='Symbolic two-way links connect investment, employment and location decisions. Growth may redistribute within the region; a project does not guarantee a fixed number of new residents.';}
 }
 if(k==='city-mumbai-migration'){
 src='migration';
 if(v==='routes'){b=title('DIFFERENT ORIGINS, SEVERAL MOTIVES')+box(20,65,180,'Elsewhere in India','National migration')+box(240,65,180,'Across India’s border','International migration')+box(110,235,220,'Mumbai','Work / study / family / safety')+path('M110 145L185 225M330 145L255 225')+dot(110+75*t,145+80*t)+dot(330-75*t,145+80*t);c='Illustrative arrival routes, not a map or measured comparison of migration volumes. National and international moves have varied causes; historical refugee movements and current moves need distinct evidence.';}
 else if(v==='communities'){b=title('DHARAVI: NAMED COMMUNITY CONNECTIONS')+box(20,80,190,'Gujarati Kumbhar potters','Craft and family networks')+box(230,80,190,'Uttar Pradesh embroiderers','Work and social connections')+box(60,235,320,'Neighbourhood development','Homes / workshops / community institutions')+path('M110 160L175 225M330 160L265 225')+tx(20,330,'Local history, not one identity for every resident',11);c='The project authority’s history gives named examples of occupational and community networks. Ethnicity, language, religion, nationality and birthplace are not interchangeable, and occupations and identities vary.';}
 else if(v==='services'){b=title('RESIDENTS BOTH USE AND PROVIDE SERVICES')+box(20,75,180,'New and existing residents','Varied ages / resources')+box(240,75,180,'Housing and services','Staff / users / capacity')+path('M105 190H335M335 255H105')+dot(105+230*t,190)+dot(335-230*t,255)+tx(20,325,'Supply, affordability and public investment mediate impacts',11);c='Two-way tokens represent contribution and use. Migration can alter demand and the workforce, but provision, age structure, resources and funding influence local outcomes. No measured service rate is shown.';}
 else{b=title('COMPOSITION MATTERS, NOT ONLY TOTAL ARRIVALS')+box(20,70,185,'Working-age residents','Jobs / skills / commuting')+box(235,70,185,'Children and older people','School / care / varied needs')+box(50,230,340,'Households are not identical','Age / size / income / tenure / support')+tx(20,330,'Illustrative comparison, not a population pyramid',11);c='The same arrival total can include different ages and household types. No invented age percentages or ethnic profile is assigned to Mumbai; proper population-pyramid and local data analysis remain separate.';}
 }
 if(k==='city-mumbai-inequality'){
 if(v==='housing')return mumbaiEvidence('housing');src='inequality';
 if(v==='opportunity'){b=title('VALUABLE LAND, UNEQUAL ACCESS TO REWARDS')+box(20,65,185,'Business investment','High-value jobs and land')+box(235,65,185,'Access and ownership','Skills / assets / networks')+path('M110 170H330')+dot(110+220*t,170)+box(65,235,310,'Different resident outcomes','Wages / rent / security / displacement');c='Symbolic links show how asset ownership, job access and rising costs can distribute growth unevenly. Nearby commercial wealth does not establish the income of each resident.';}
 else if(v==='livelihoods'){b=title('DHARAVI HAS WORK AND ECONOMIC CONNECTIONS')+box(20,65,185,'Craft and production','Pottery / leather / garments')+box(235,65,185,'Materials and services','Recycling / local enterprise')+homes(35,200,5)+homes(265,200,5)+tx(20,282,'Homes and workplaces can share dense space',13)+tx(20,330,'Varied livelihoods, income and conditions',12);c='Official local history records diverse small enterprises. Recognising residents’ contribution does not imply equal incomes, safe conditions or adequate services in every home or workplace.';}
 else{b=title('QUALITY OF LIFE: COMPARE SEVERAL DIMENSIONS')+box(20,65,185,'Resources and housing','Income / space / security')+box(235,65,185,'Services and health','Water / sanitation / access')+box(20,225,185,'Work and opportunity','Skills / rights / connections')+box(235,225,185,'Environment','Hazards / public space')+path('M110 150L330 215M330 150L110 215')+dot(110+220*t,150+65*t)+dot(330-220*t,150+65*t);c='Interacting dimensions explain why quality of life varies. This is not a numerical index or evidence that one housing category determines every outcome; compare dated indicators and residents’ accounts.';}
 }
 return fig(b,c)+(src?source(src):'');
}
